﻿using System;
using System.Data;
using System.Windows.Controls;
using GalaSoft.MvvmLight.Command;

namespace WarframeDropRatesData.Views.Converters
{
    internal class DataGridMouseDoubleClickConverter : IEventArgsConverter
    {
        public object Convert(object value, object parameter)
        {
            var dataGrid = parameter as DataGrid;

            if (dataGrid == null || dataGrid.SelectedCells.Count == 0)
            {
                return null;
            }

            switch (dataGrid.SelectionUnit)
            {
                case DataGridSelectionUnit.Cell:
                    var cellInfo = dataGrid.SelectedCells[0];
                    int index = cellInfo.Column.DisplayIndex;
                    var row = cellInfo.Item as DataRowView;
                    return row?[index].ToString();

                case DataGridSelectionUnit.FullRow:
                    var dataRow = (DataRowView)dataGrid.SelectedItem;
                    index = dataGrid.CurrentCell.Column.DisplayIndex;
                    return dataRow.Row.ItemArray[index].ToString();

                case DataGridSelectionUnit.CellOrRowHeader:
                    return null;

                default:
                    throw new ArgumentOutOfRangeException();
            }
        }
    }
}
